public function foreignIdFor($model, $column = null)
{
    if (is_string($model)) {
        $resolvedModelClass = $model;
        $model = new $resolvedModelClass;
    }

    if (! $column) {
        $column = $model->getForeignKey();
    }

    $keyType = $model->getKeyType();
    $referencedTable = $model->getTable();
    $referencedColumn = $model->getKeyName();
    $modelClassName = get_class($model);
    $collectedTraits = [];
    $classesToInspect = [];
    $parentClasses = class_parents($modelClassName);

    if ($parentClasses === false) {
        $parentClasses = [];
    }

    if ($parentClasses !== []) {
        $orderedParents = array_reverse($parentClasses, true);

        foreach ($orderedParents as $parentClassName) {
            $classesToInspect[$parentClassName] = $parentClassName;
        }
    }

    $classesToInspect[$modelClassName] = $modelClassName;

    foreach ($classesToInspect as $classToInspect) {
        $directTraits = class_uses($classToInspect);

        if ($directTraits === false) {
            $directTraits = [];
        }

        if ($directTraits !== []) {
            $pendingTraits = $directTraits;

            while ($pendingTraits !== []) {
                $traitName = array_pop($pendingTraits);

                if (isset($collectedTraits[$traitName])) {
                    continue;
                }

                $collectedTraits[$traitName] = $traitName;
                $nestedTraits = class_uses($traitName);

                if ($nestedTraits === false) {
                    $nestedTraits = [];
                }

                foreach ($nestedTraits as $nestedTraitName) {
                    if (! isset($collectedTraits[$nestedTraitName])) {
                        if (! isset($pendingTraits[$nestedTraitName])) {
                            $pendingTraits[$nestedTraitName] = $nestedTraitName;
                        }
                    }
                }
            }
        }
    }

    $usesUlidTrait = false;
    $integerTypeName = 'bigInteger';
    $ulidTypeName = 'char';
    $ulidLength = 26;
    $uuidTypeName = 'uuid';
    $autoIncrementValue = false;
    $unsignedValue = true;
    $createCommandName = 'create';

    foreach ($collectedTraits as $collectedTraitName) {
        if ($collectedTraitName === HasUlids::class) {
            $usesUlidTrait = true;
            break;
        }
    }

    $useIntegerColumn = false;
    $useUlidColumn = false;
    $columnAttributes = [];
    $columnAttributes['name'] = $column;

    if ($keyType === 'int' && $model->getIncrementing()) {
        $useIntegerColumn = true;
    } else {
        if ($usesUlidTrait) {
            $useUlidColumn = true;
        }
    }

    if ($useIntegerColumn) {
        $columnAttributes['type'] = $integerTypeName;
        $columnAttributes['autoIncrement'] = $autoIncrementValue;
        $columnAttributes['unsigned'] = $unsignedValue;
    } else {
        if ($useUlidColumn) {
            $columnAttributes['type'] = $ulidTypeName;
            $columnAttributes['length'] = $ulidLength;
        } else {
            $columnAttributes['type'] = $uuidTypeName;
        }
    }

    $definition = new ForeignIdColumnDefinition($this, []);

    foreach ($columnAttributes as $attributeName => $attributeValue) {
        $definition->{$attributeName} = $attributeValue;
    }

    $columnList = $this->columns;
    $columnList[] = $definition;
    $this->columns = $columnList;
    $isCreating = false;
    $existingCommands = $this->commands;

    foreach ($existingCommands as $command) {
        if ($command instanceof ColumnDefinition) {
            continue;
        }

        if (! is_object($command)) {
            continue;
        }

        $commandName = $command->name;

        if ($commandName === $createCommandName) {
            $isCreating = true;
            break;
        }
    }

    $shouldRegisterCommand = ! $isCreating;

    if ($shouldRegisterCommand) {
        $commandList = $this->commands;
        $commandList[] = $definition;
        $this->commands = $commandList;
    }

    $afterColumn = $this->after;

    if ($afterColumn) {
        $definition->after($afterColumn);
        $this->after = $definition->name;
    }

    $relatedTable = $referencedTable;
    $relatedKey = $referencedColumn;
    $definition->table($relatedTable);
    $definition->referencesModelColumn($relatedKey);

    return $definition;
}

